void TRTBEVFormerNode::callback(
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_fl_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_f_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_fr_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_bl_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_b_img,
  const sensor_msgs::msg::Image::ConstSharedPtr & msg_br_img,
  const autoware_localization_msgs::msg::KinematicState::ConstSharedPtr & can_bus_msg)
{
  auto t_preprocess_start = std::chrono::steady_clock::now();

  std::vector<float> latest_can_bus = extractCanBusFromKinematicState(can_bus_msg);

  // Create vector of image messages for transform calculation
  std::vector<sensor_msgs::msg::Image::ConstSharedPtr> image_msgs = {
    msg_f_img, msg_fr_img, msg_fl_img, msg_b_img, msg_bl_img, msg_br_img};

  rclcpp::Time ref_time = this->now();
  RCLCPP_DEBUG(this->get_logger(), "Ref time Initialized");
  Eigen::Quaterniond ego2global_rot;
  Eigen::Translation3d ego2global_trans;

  try {
    if (tf_buffer_->canTransform(
          "world", "base_link", ref_time, rclcpp::Duration::from_seconds(0.5))) {
      auto tf_ego2global = tf_buffer_->lookupTransform("world", "base_link", ref_time);
      getTransform(tf_ego2global, ego2global_rot, ego2global_trans);
      RCLCPP_DEBUG(this->get_logger(), "Got ego2global transform for CAN bus processing");
    } else {
      RCLCPP_WARN(
        this->get_logger(), "Missing world->base_link transform at time %f", ref_time.seconds());
      return;
    }
  } catch (tf2::TransformException & ex) {
    RCLCPP_WARN(
      this->get_logger(), "Transform lookup failed at time %f: %s", ref_time.seconds(), ex.what());
    return;
  }
  RCLCPP_DEBUG(this->get_logger(), "Transform functions done");

  // Update sensor2lidar transforms for each camera with its own timestamp
  calculateSensor2LidarTransformsFromTF(image_msgs, ego2global_rot, ego2global_trans);

  // Image conversion
  cv::Mat img_fl, img_f, img_fr, img_bl, img_b, img_br;
  try {
    img_fl = cloneAndResize(msg_fl_img);
    img_f = cloneAndResize(msg_f_img);
    img_fr = cloneAndResize(msg_fr_img);
    img_bl = cloneAndResize(msg_bl_img);
    img_b = cloneAndResize(msg_b_img);
    img_br = cloneAndResize(msg_br_img);
  } catch (cv_bridge::Exception & e) {
    RCLCPP_ERROR(this->get_logger(), "CV bridge exception: %s", e.what());
    return;
  }

  std::vector<cv::Mat> raw_images = {img_f, img_fr, img_fl, img_b, img_bl, img_br};

  // Processing can_bus data
  std::vector<float> ego2global_translation_data = {
    static_cast<float>(ego2global_trans.x()), static_cast<float>(ego2global_trans.y()),
    static_cast<float>(ego2global_trans.z())};

  std::vector<float> ego2global_rotation_data = {
    static_cast<float>(ego2global_rot.w()), static_cast<float>(ego2global_rot.x()),
    static_cast<float>(ego2global_rot.y()), static_cast<float>(ego2global_rot.z())};

  std::vector<float> initial_can_bus = data_manager_->processCanBus(
    ego2global_translation_data, ego2global_rotation_data, latest_can_bus);

  if (!preprocessor_) {
    RCLCPP_ERROR(this->get_logger(), "Preprocessor is not initialized!");
    return;
  }

  // Use the preprocessor to process the images
  BEVFormerStructuredInput structured_input = preprocessor_->preprocessImages(
    raw_images, sensor2lidar_rotation_, sensor2lidar_translation_, cams_intrin_);

  auto t_preprocess_end = std::chrono::steady_clock::now();
  RCLCPP_INFO(
    this->get_logger(), "Pre-processing : %ld ms",
    std::chrono::duration_cast<std::chrono::milliseconds>(t_preprocess_end - t_preprocess_start)
      .count());

  auto t_inference_start = t_preprocess_end;

  // Get use_prev_bev flag ONCE at the beginning of inference phase
  float use_prev_bev = data_manager_->getUsePrevBev();

  // Apply temporal processing with the determined flag
  std::vector<float> processed_can_bus =
    data_manager_->processCanbusWithTemporal(initial_can_bus, use_prev_bev);

  // Get the previous BEV features
  const std::vector<float> & prev_bev = data_manager_->getPrevBev();

  if (!inference_engine_ || !inference_engine_->isInitialized()) {
    RCLCPP_ERROR(this->get_logger(), "Inference engine is not initialized!");
    return;
  }

  // Run inference
  auto [outputs_classes, outputs_coords, bev_embed] = inference_engine_->runInference(
    structured_input.img_tensor, prev_bev, use_prev_bev, processed_can_bus,
    structured_input.lidar2img_flat);

  auto t_inference_end = std::chrono::steady_clock::now();
  RCLCPP_INFO(
    this->get_logger(), "Inference : %ld ms",
    std::chrono::duration_cast<std::chrono::milliseconds>(t_inference_end - t_inference_start)
      .count());

  auto t_postprocess_start = t_inference_end;

  // Reshape outputs
  std::map<std::string, std::vector<float>> rawOutputs;
  rawOutputs["outputs_classes"] = outputs_classes;
  rawOutputs["outputs_coords"] = outputs_coords;
  rawOutputs["bev_embed"] = bev_embed;

  if (rawOutputs.count("bev_embed")) {
    data_manager_->updatePrevBev(std::move(rawOutputs["bev_embed"]));
    rawOutputs.erase("bev_embed");
  } else {
    RCLCPP_WARN(this->get_logger(), "Reshaped BEV embedding not found in outputs!");
  }

  // Update prev_frame_info AFTER inference
  data_manager_->updatePrevFrameInfo();

  // Post Processing
  std::map<std::string, std::vector<double>> reshapedOutputs;
  for (const auto & [key, vec] : rawOutputs) {
    reshapedOutputs[key] = std::vector<double>(vec.begin(), vec.end());
  }

  int max_num = this->get_parameter_or("post_process_params.max_num", 300);

  PostProcessor postProcessor(
    model_shape_params_["nb_dec"], model_shape_params_["num_query"],
    model_shape_params_["num_classes"], model_shape_params_["code_size"],
    model_shape_params_["bev_h"], model_shape_params_["bev_w"], score_thre_, max_num, pc_range_,
    post_center_range_);

  auto t_postprocess_end = std::chrono::steady_clock::now();
  RCLCPP_INFO(
    this->get_logger(), "Post-processing : %ld ms",
    std::chrono::duration_cast<std::chrono::milliseconds>(t_postprocess_end - t_postprocess_start)
      .count());

  std::vector<Box3D> batch_results;
  try {
    batch_results = postProcessor.post_process(reshapedOutputs);
    RCLCPP_INFO(this->get_logger(), "Detections: %zu", batch_results.size());
    RCLCPP_INFO(this->get_logger(), "--------------------------------------------------");
  } catch (const std::exception & e) {
    RCLCPP_ERROR(this->get_logger(), "Post-process failed: %s", e.what());
    return;
  }

  autoware_perception_msgs::msg::DetectedObjects bevformer_objects;
  bevformer_objects.header.frame_id = "LIDAR_TOP";
  bevformer_objects.header.stamp = msg_f_img->header.stamp;

  box3DToDetectedObjects(batch_results, bevformer_objects, class_names_, score_thre_, has_twist_);

  pub_boxes_->publish(bevformer_objects);

  // Only publish debug markers if debug mode is enabled
  if (debug_mode_ && pub_markers_) {
    publishDebugMarkers(pub_markers_, bevformer_objects);
  }
}

std::vector<float> TRTBEVFormerNode::extractCanBusFromKinematicState(
  const autoware_localization_msgs::msg::KinematicState::ConstSharedPtr & kinematic_state_msg)
{
  std::vector<float> can_bus_data(18, 0.0f);

  // Map position (3 values)
  can_bus_data[0] = static_cast<float>(kinematic_state_msg->pose_with_covariance.pose.position.x);
  can_bus_data[1] = static_cast<float>(kinematic_state_msg->pose_with_covariance.pose.position.y);
  can_bus_data[2] = static_cast<float>(kinematic_state_msg->pose_with_covariance.pose.position.z);

  // Map orientation (4 values: w, x, y, z)
  can_bus_data[3] =
    static_cast<float>(kinematic_state_msg->pose_with_covariance.pose.orientation.w);
  can_bus_data[4] =
    static_cast<float>(kinematic_state_msg->pose_with_covariance.pose.orientation.x);
  can_bus_data[5] =
    static_cast<float>(kinematic_state_msg->pose_with_covariance.pose.orientation.y);
  can_bus_data[6] =
    static_cast<float>(kinematic_state_msg->pose_with_covariance.pose.orientation.z);

  // Map linear velocity (3 values)
  can_bus_data[7] = static_cast<float>(kinematic_state_msg->twist_with_covariance.twist.linear.x);
  can_bus_data[8] = static_cast<float>(kinematic_state_msg->twist_with_covariance.twist.linear.y);
  can_bus_data[9] = static_cast<float>(kinematic_state_msg->twist_with_covariance.twist.linear.z);

  // Map angular velocity (3 values)
  can_bus_data[10] = static_cast<float>(kinematic_state_msg->twist_with_covariance.twist.angular.x);
  can_bus_data[11] = static_cast<float>(kinematic_state_msg->twist_with_covariance.twist.angular.y);
  can_bus_data[12] = static_cast<float>(kinematic_state_msg->twist_with_covariance.twist.angular.z);

  // Map linear acceleration (3 values)
  can_bus_data[13] = static_cast<float>(kinematic_state_msg->accel_with_covariance.accel.linear.x);
  can_bus_data[14] = static_cast<float>(kinematic_state_msg->accel_with_covariance.accel.linear.y);
  can_bus_data[15] = static_cast<float>(kinematic_state_msg->accel_with_covariance.accel.linear.z);

  // Padding for compatibility (2 values)
  can_bus_data[16] = 0.0f;
  can_bus_data[17] = 0.0f;

  return can_bus_data;
}

void TRTBEVFormerNode::calculateSensor2LidarTransformsFromTF(
  const std::vector<sensor_msgs::msg::Image::ConstSharedPtr> & image_msgs,
  const Eigen::Quaterniond & ego2global_rot_ref, const Eigen::Translation3d & ego2global_trans_ref)
{
  if (!lidar2ego_transforms_ready_) {
    RCLCPP_ERROR(this->get_logger(), "Static lidar2ego transforms not ready");
    return;
  }

  // Use static lidar2ego and ego2global from LiDAR timestamp
  Eigen::Matrix3d l2e_r_mat = lidar2ego_rot_static_.cast<double>().toRotationMatrix();
  Eigen::RowVector3d l2e_t = lidar2ego_trans_static_.cast<double>().vector().transpose();
  Eigen::Matrix3d e2g_r_mat = ego2global_rot_ref.toRotationMatrix();
  Eigen::RowVector3d e2g_t = ego2global_trans_ref.vector().transpose();

  std::vector<std::string> camera_names = {"CAM_FRONT", "CAM_FRONT_RIGHT", "CAM_FRONT_LEFT",
                                           "CAM_BACK",  "CAM_BACK_LEFT",   "CAM_BACK_RIGHT"};

  for (size_t i = 0; i < img_N_; ++i) {
    if (i >= image_msgs.size()) {
      RCLCPP_ERROR(this->get_logger(), "Camera %zu data not available", i);
      continue;
    }

    std::string camera_name = camera_names[i];
    rclcpp::Time camera_timestamp = image_msgs[i]->header.stamp;

    // Get sensor2ego transforms
    Eigen::Matrix3d l2e_r_s_mat = cams2ego_rot_[i].cast<double>().toRotationMatrix();
    Eigen::RowVector3d l2e_t_s = cams2ego_trans_[i].cast<double>().vector().transpose();

    // Get ego2global at camera timestamp
    Eigen::Quaterniond ego2global_rot_cam = Eigen::Quaterniond::Identity();
    Eigen::Translation3d ego2global_trans_cam = Eigen::Translation3d::Identity();
    bool got_camera_transform = false;
    try {
      if (tf_buffer_->canTransform(
            "world", "base_link", camera_timestamp, rclcpp::Duration::from_seconds(0.1))) {
        auto tf_ego2global_cam = tf_buffer_->lookupTransform(
          "world", "base_link", camera_timestamp, rclcpp::Duration::from_seconds(0.1));

        ego2global_rot_cam = Eigen::Quaterniond(
          tf_ego2global_cam.transform.rotation.w, tf_ego2global_cam.transform.rotation.x,
          tf_ego2global_cam.transform.rotation.y, tf_ego2global_cam.transform.rotation.z);
        ego2global_trans_cam = Eigen::Translation3d(
          tf_ego2global_cam.transform.translation.x, tf_ego2global_cam.transform.translation.y,
          tf_ego2global_cam.transform.translation.z);
        got_camera_transform = true;
      }
    } catch (tf2::TransformException & ex) {
      RCLCPP_DEBUG(
        this->get_logger(), "Camera %s: Failed exact lookup: %s", camera_name.c_str(), ex.what());
    }
    if (!got_camera_transform) {
      RCLCPP_DEBUG(this->get_logger(), "Camera transform for ego2global are not found");
    }

    Eigen::Matrix3d e2g_r_s_mat = ego2global_rot_cam.toRotationMatrix();
    Eigen::RowVector3d e2g_t_s = ego2global_trans_cam.vector().transpose();

    // Compute matrix inverses
    Eigen::Matrix3d e2g_r_mat_inv = e2g_r_mat.inverse();
    Eigen::Matrix3d l2e_r_mat_inv = l2e_r_mat.inverse();

    // Calculate R matrix
    Eigen::Matrix3d R = (l2e_r_s_mat.transpose() * e2g_r_s_mat.transpose()) *
                        (e2g_r_mat_inv.transpose() * l2e_r_mat_inv.transpose());

    // Calculate T vector
    Eigen::Matrix3d combined_inv = e2g_r_mat_inv.transpose() * l2e_r_mat_inv.transpose();
    Eigen::RowVector3d T_initial = (l2e_t_s * e2g_r_s_mat.transpose() + e2g_t_s) * combined_inv;

    Eigen::RowVector3d subtract_term1 = e2g_t * combined_inv;
    Eigen::RowVector3d subtract_term2 = l2e_t * l2e_r_mat_inv.transpose();

    Eigen::RowVector3d subtract_sum = subtract_term1 + subtract_term2;

    Eigen::RowVector3d T_row = T_initial - (subtract_term1 + subtract_term2);

    Eigen::Vector3d T = T_row.transpose();

    sensor2lidar_rotation_[i] = R.transpose();
    sensor2lidar_translation_[i] = T;
  }
}

BEVFormerStructuredInput BEVFormerPreprocessor::preprocessImages(
  const std::vector<cv::Mat> & raw_images,
  const std::vector<Eigen::Matrix3d> & sensor2lidar_rotation,
  const std::vector<Eigen::Vector3d> & sensor2lidar_translation,
  const std::vector<Eigen::Matrix3d> & cam_intrinsics)
{
  BEVFormerStructuredInput result;

  // Check if we have 6 images
  if (raw_images.size() != 6) {
    RCLCPP_ERROR(
      logger_, "Expected 6 images in bevformer preprocessor, got %zu", raw_images.size());
    return result;
  }

  // Create lidar2img matrices
  std::vector<cv::Mat> lidar2img_matrices =
    createLidar2ImgMatrices(sensor2lidar_rotation, sensor2lidar_translation, cam_intrinsics);

  if (lidar2img_matrices.size() != 6) {
    RCLCPP_ERROR(logger_, "Failed to create all 6 lidar2img matrices");
    return result;
  }

  // Create metadata for preprocessing
  bevformer::preprocessing::DataDict metadata;
  metadata["mean"] = mean_;
  metadata["std"] = std_;
  metadata["to_rgb"] = std::vector<float>{to_rgb_ ? 1.0f : 0.0f};

  // Run the preprocessing pipeline
  auto processed_results = pipeline_->processImages(raw_images, lidar2img_matrices, metadata);

  // Extract processed data
  std::vector<cv::Mat> processed_images;
  if (std::holds_alternative<std::vector<cv::Mat>>(processed_results["img"])) {
    processed_images = std::get<std::vector<cv::Mat>>(processed_results["img"]);
  } else {
    RCLCPP_ERROR(logger_, "Failed to get processed images from pipeline");
    return result;
  }

  // Get final lidar2img matrices
  std::vector<cv::Mat> final_lidar2img_matrices;
  if (
    processed_results.count("lidar2img") &&
    std::holds_alternative<std::vector<cv::Mat>>(processed_results["lidar2img"])) {
    final_lidar2img_matrices = std::get<std::vector<cv::Mat>>(processed_results["lidar2img"]);
  } else {
    final_lidar2img_matrices = lidar2img_matrices;
  }

  // Create image tensor and flatten lidar2img matrices
  result.img_tensor = data_loader_.createImageTensor(processed_images);
  result.lidar2img_flat = flattenLidar2ImgMatrices(final_lidar2img_matrices);

  return result;
}

std::vector<cv::Mat> BEVFormerPreprocessor::createLidar2ImgMatrices(
  const std::vector<Eigen::Matrix3d> & sensor2lidar_rotation,
  const std::vector<Eigen::Vector3d> & sensor2lidar_translation,
  const std::vector<Eigen::Matrix3d> & cam_intrinsics)
{
  std::vector<cv::Mat> lidar2img_matrices;

  // Check input sizes
  if (
    sensor2lidar_rotation.size() != 6 || sensor2lidar_translation.size() != 6 ||
    cam_intrinsics.size() != 6) {
    RCLCPP_ERROR(
      logger_, "Invalid input sizes for createLidar2ImgMatrices: %zu, %zu, %zu",
      sensor2lidar_rotation.size(), sensor2lidar_translation.size(), cam_intrinsics.size());
    return lidar2img_matrices;
  }

  // Calculate transformation matrices for each camera
  for (size_t i = 0; i < sensor2lidar_rotation.size(); ++i) {
    Eigen::Matrix3d lidar2cam_r = sensor2lidar_rotation[i].inverse();
    Eigen::Vector3d lidar2cam_t = sensor2lidar_translation[i].transpose() * lidar2cam_r.transpose();

    // Create 4x4 lidar2cam matrix
    Eigen::Matrix4d lidar2cam_rt = Eigen::Matrix4d::Identity();
    lidar2cam_rt.block<3, 3>(0, 0) = lidar2cam_r.transpose();
    lidar2cam_rt.block<3, 1>(0, 3) = Eigen::Vector3d::Zero();
    lidar2cam_rt.block<1, 3>(3, 0) = -lidar2cam_t.transpose();
    lidar2cam_rt(3, 3) = 1.0;

    // Create viewpad with intrinsics
    Eigen::Matrix4d viewpad = Eigen::Matrix4d::Identity();
    viewpad.block<3, 3>(0, 0) = cam_intrinsics[i];

    Eigen::Matrix4d lidar2img_rt = viewpad * lidar2cam_rt.transpose();

    // Convert to OpenCV matrix (float, as OpenCV expects CV_32F)
    cv::Mat lidar2img_cv = cv::Mat::zeros(4, 4, CV_32F);
    for (int row = 0; row < 4; ++row) {
      for (int col = 0; col < 4; ++col) {
        lidar2img_cv.at<float>(row, col) = static_cast<float>(lidar2img_rt(row, col));
      }
    }

    lidar2img_matrices.push_back(lidar2img_cv);
  }

  return lidar2img_matrices;
}

DataDict BEVPreprocessingPipeline::processImages(
  const std::vector<cv::Mat> & images, const std::vector<cv::Mat> & lidar2img_matrices,
  const DataDict & metadata)
{
  DataDict results;

  if (images.size() != 6) {
    std::cerr << "Warning: Expected 6 images, received " << images.size() << std::endl;
  }

  std::vector<cv::Mat> image_copies;
  for (const auto & img : images) {
    cv::Mat float_img;
    if (img.type() != CV_32FC3) {
      img.convertTo(float_img, CV_32FC3);
    } else {
      float_img = img.clone();
    }
    image_copies.push_back(float_img);
  }
  results["img"] = image_copies;

  // Store lidar2img matrices directly from the parameters
  results["lidar2img"] = lidar2img_matrices;

  // Copy only metadata of normalization
  if (metadata.count("mean")) {
    results["mean"] = metadata.at("mean");
  }
  if (metadata.count("std")) {
    results["std"] = metadata.at("std");
  }
  if (metadata.count("to_rgb")) {
    results["to_rgb"] = metadata.at("to_rgb");
  }

  try {
    // Apply normalization and augmentation
    results = (*normalize_multiview_images_)(results);
    results = (*multi_scale_flip_aug_)(results);
  } catch (const std::exception & e) {
    std::cerr << "Error (Image Preprocessing pipeline) : " << e.what() << std::endl;
  }

  return results;
}

DataDict NormalizeMultiviewImage::operator()(DataDict results)
{
  if (!results.count("img") || !std::holds_alternative<std::vector<cv::Mat>>(results["img"])) {
    std::cerr << "No images found in results" << std::endl;
    return results;
  }

  std::vector<cv::Mat> images = std::get<std::vector<cv::Mat>>(results["img"]);
  std::vector<cv::Mat> normalized_images;
  normalized_images.reserve(images.size());

  for (const auto & img : images) {
    cv::Mat normalized;

    // Convert BGR to RGB if needed
    if (to_rgb_ && img.channels() == 3) {
      cv::cvtColor(img, normalized, cv::COLOR_BGR2RGB);
    } else {
      normalized = img.clone();
    }

    // Ensure float format
    if (normalized.type() != CV_32FC3) {
      normalized.convertTo(normalized, CV_32FC3);
    }

    // Apply normalization directly to each channel
    cv::Mat channels[3];
    cv::split(normalized, channels);

    for (int c = 0; c < 3; ++c) {
      channels[c] = (channels[c] - mean_[c]) / std_[c];
    }

    cv::merge(channels, 3, normalized);
    normalized_images.push_back(normalized);
  }

  results["img"] = normalized_images;
  results.setNestedDict("img_norm_cfg");

  auto & img_norm_cfg = results.getNestedDict("img_norm_cfg");
  img_norm_cfg["mean"] = std::vector<float>(mean_.begin(), mean_.end());
  img_norm_cfg["std"] = std::vector<float>(std_.begin(), std_.end());
  img_norm_cfg["to_rgb"] = to_rgb_;

  return results;
}

DataDict MultiScaleFlipAug3D::operator()(DataDict results)
{
  // Create a copy to avoid modifying the original
  DataDict augmented_results = results;

  if (compose_) {
    augmented_results = (*compose_)(augmented_results);
  }

  return augmented_results;
}

cv::Mat BEVFormerDataLoader::createImageTensor(const std::vector<cv::Mat> & images)
{
  if (images.size() != 6) {
    RCLCPP_ERROR(
      rclcpp::get_logger("bevformer_data_loader"), "Expected 6 images, got %zu", images.size());
    return cv::Mat();
  }

  // Get dimensions from first image (now in CHW format)
  const cv::Mat & first_img = images[0];
  const int channels = first_img.size[0];
  const int img_h = first_img.size[1];
  const int img_w = first_img.size[2];
  const size_t batch_size = 1;
  const size_t num_cams = 6;
  const size_t total_elements = batch_size * num_cams * channels * img_h * img_w;

  // Validate input images
  for (size_t i = 0; i < images.size(); ++i) {
    if (images[i].dims != 3) {  // Check for 3D tensor (CHW format)
      RCLCPP_ERROR(
        rclcpp::get_logger("bevformer_data_loader"),
        "Image %zu is not in CHW format (expected 3 dimensions)", i);
      return cv::Mat();
    }
    if (images[i].size[0] != channels || images[i].size[1] != img_h || images[i].size[2] != img_w) {
      RCLCPP_ERROR(
        rclcpp::get_logger("bevformer_data_loader"),
        "Image %zu has wrong dimensions: [%d, %d, %d], expected [%d, %d, %d]", i, images[i].size[0],
        images[i].size[1], images[i].size[2], channels, img_h, img_w);
      return cv::Mat();
    }
  }

  // Create output tensor
  cv::Mat tensor(1, total_elements, CV_32F);
  float * tensor_data = tensor.ptr<float>();

  // Fill tensor with correct memory layout [1, 6, 3, H, W]
  for (size_t cam_idx = 0; cam_idx < num_cams; cam_idx++) {
    const cv::Mat & img = images[cam_idx];

    // Since input is already in CHW format, we can copy directly
    size_t cam_offset = cam_idx * channels * img_h * img_w;
    const float * img_data = img.ptr<float>();

    // Copy the entire camera's data at once
    std::memcpy(tensor_data + cam_offset, img_data, channels * img_h * img_w * sizeof(float));
  }

  return tensor;
}

std::vector<float> BEVFormerPreprocessor::flattenLidar2ImgMatrices(
  const std::vector<cv::Mat> & lidar2img_matrices)
{
  std::vector<float> lidar2img_flat;
  lidar2img_flat.reserve(6 * 4 * 4);  // 6 cameras, 4x4 matrices

  for (const auto & mat : lidar2img_matrices) {
    if (mat.rows != 4 || mat.cols != 4) {
      RCLCPP_ERROR(logger_, "Invalid lidar2img matrix size: %dx%d", mat.rows, mat.cols);
      continue;
    }

    for (int i = 0; i < mat.rows; ++i) {
      for (int j = 0; j < mat.cols; ++j) {
        lidar2img_flat.push_back(mat.at<float>(i, j));
      }
    }
  }

  return lidar2img_flat;
}

BEVFormerInferenceEngine::runInference(
  const cv::Mat & img_tensor, const std::vector<float> & prev_bev, float use_prev_bev,
  const std::vector<float> & can_bus, const std::vector<float> & lidar2img_flat)
{
  if (!initialized_) {
    RCLCPP_ERROR(logger_, "Inference engine not initialized");
    return std::make_tuple(std::vector<float>(), std::vector<float>(), std::vector<float>());
  }

  // Validate inputs
  if (!validateInputs(img_tensor, prev_bev, can_bus, lidar2img_flat)) {
    return std::make_tuple(std::vector<float>(), std::vector<float>(), std::vector<float>());
  }

  // Convert image tensor to vector for comparison
  std::vector<float> img_tensor_vec(
    img_tensor.ptr<float>(), img_tensor.ptr<float>() + img_tensor.total());

  // Find tensor indices by name
  int img_tensor_idx = -1, prev_bev_idx = -1, use_prev_bev_idx = -1, can_bus_idx = -1,
      lidar2img_idx = -1;
  int bev_embed_idx = -1, outputs_classes_idx = -1, outputs_coords_idx = -1;

  for (int i = 0; i < engine_->getNbIOTensors(); i++) {
    const char * name = engine_->getIOTensorName(i);
    std::string tensor_name(name);
    if (tensor_name == "image") {
      img_tensor_idx = i;
    } else if (tensor_name == "prev_bev") {
      prev_bev_idx = i;
    } else if (tensor_name == "use_prev_bev") {
      use_prev_bev_idx = i;
    } else if (tensor_name == "can_bus") {
      can_bus_idx = i;
    } else if (tensor_name == "lidar2img") {
      lidar2img_idx = i;
    } else if (tensor_name == "bev_embed") {
      bev_embed_idx = i;
    } else if (tensor_name == "outputs_classes") {
      outputs_classes_idx = i;
    } else if (tensor_name == "outputs_coords") {
      outputs_coords_idx = i;
    }
  }

  if (
    img_tensor_idx == -1 || prev_bev_idx == -1 || use_prev_bev_idx == -1 || can_bus_idx == -1 ||
    lidar2img_idx == -1 || bev_embed_idx == -1 || outputs_classes_idx == -1 ||
    outputs_coords_idx == -1) {
    RCLCPP_ERROR(logger_, "Failed to find all required tensors in the engine");
    return std::make_tuple(std::vector<float>(), std::vector<float>(), std::vector<float>());
  }

  // Calculate output buffer sizes
  size_t bev_embed_size = 1;
  size_t outputs_classes_size = 1;
  size_t outputs_coords_size = 1;

  const nvinfer1::Dims bev_embed_dims =
    engine_->getTensorShape(engine_->getIOTensorName(bev_embed_idx));
  const nvinfer1::Dims outputs_classes_dims =
    engine_->getTensorShape(engine_->getIOTensorName(outputs_classes_idx));
  const nvinfer1::Dims outputs_coords_dims =
    engine_->getTensorShape(engine_->getIOTensorName(outputs_coords_idx));

  for (int i = 0; i < bev_embed_dims.nbDims; i++) {
    bev_embed_size *= bev_embed_dims.d[i];
  }
  for (int i = 0; i < outputs_classes_dims.nbDims; i++) {
    outputs_classes_size *= outputs_classes_dims.d[i];
  }
  for (int i = 0; i < outputs_coords_dims.nbDims; i++) {
    outputs_coords_size *= outputs_coords_dims.d[i];
  }

  // Create CUDA stream for inference
  cudaStream_t stream;
  CHECK_CUDA(cudaStreamCreate(&stream));

  cudaEvent_t start_event, end_event;
  CHECK_CUDA(cudaEventCreate(&start_event));
  CHECK_CUDA(cudaEventCreate(&end_event));

  std::vector<float> outputs_classes(outputs_classes_size);
  std::vector<float> outputs_coords(outputs_coords_size);
  std::vector<float> bev_embed_output(bev_embed_size);

  try {
    // Use RAII for CUDA memory management
    CudaMemoryManager cuda_mem;

    // Allocate device memory for inputs and outputs
    void * d_img_tensor = cuda_mem.allocate(sizeof(float) * img_tensor.total());
    void * d_prev_bev = cuda_mem.allocate(sizeof(float) * prev_bev.size());
    void * d_use_prev_bev = cuda_mem.allocate(sizeof(float));
    void * d_can_bus = cuda_mem.allocate(sizeof(float) * can_bus.size());
    void * d_lidar2img = cuda_mem.allocate(sizeof(float) * lidar2img_flat.size());
    void * d_bev_embed = cuda_mem.allocate(sizeof(float) * bev_embed_size);
    void * d_outputs_classes = cuda_mem.allocate(sizeof(float) * outputs_classes_size);
    void * d_outputs_coords = cuda_mem.allocate(sizeof(float) * outputs_coords_size);

    // Clear output buffers
    CHECK_CUDA(cudaMemsetAsync(d_bev_embed, 0, sizeof(float) * bev_embed_size, stream));
    CHECK_CUDA(cudaMemsetAsync(d_outputs_classes, 0, sizeof(float) * outputs_classes_size, stream));
    CHECK_CUDA(cudaMemsetAsync(d_outputs_coords, 0, sizeof(float) * outputs_coords_size, stream));

    // Copy input data to device
    CHECK_CUDA(cudaMemcpyAsync(
      d_img_tensor, img_tensor.ptr<float>(), sizeof(float) * img_tensor.total(),
      cudaMemcpyHostToDevice, stream));
    CHECK_CUDA(cudaMemcpyAsync(
      d_prev_bev, prev_bev.data(), sizeof(float) * prev_bev.size(), cudaMemcpyHostToDevice,
      stream));
    CHECK_CUDA(cudaMemcpyAsync(
      d_use_prev_bev, &use_prev_bev, sizeof(float), cudaMemcpyHostToDevice, stream));
    CHECK_CUDA(cudaMemcpyAsync(
      d_can_bus, can_bus.data(), sizeof(float) * can_bus.size(), cudaMemcpyHostToDevice, stream));
    CHECK_CUDA(cudaMemcpyAsync(
      d_lidar2img, lidar2img_flat.data(), sizeof(float) * lidar2img_flat.size(),
      cudaMemcpyHostToDevice, stream));

    CHECK_CUDA(cudaStreamSynchronize(stream));

    // Set tensor addresses
    context_->setTensorAddress(engine_->getIOTensorName(img_tensor_idx), d_img_tensor);
    context_->setTensorAddress(engine_->getIOTensorName(prev_bev_idx), d_prev_bev);
    context_->setTensorAddress(engine_->getIOTensorName(use_prev_bev_idx), d_use_prev_bev);
    context_->setTensorAddress(engine_->getIOTensorName(can_bus_idx), d_can_bus);
    context_->setTensorAddress(engine_->getIOTensorName(lidar2img_idx), d_lidar2img);
    context_->setTensorAddress(engine_->getIOTensorName(bev_embed_idx), d_bev_embed);
    context_->setTensorAddress(engine_->getIOTensorName(outputs_classes_idx), d_outputs_classes);
    context_->setTensorAddress(engine_->getIOTensorName(outputs_coords_idx), d_outputs_coords);

    // Execute inference
    CHECK_CUDA(cudaEventRecord(start_event, stream));
    CHECK_CUDA(cudaStreamSynchronize(stream));  // To ensure all data is transferred

    if (!context_->enqueueV3(stream)) {
      RCLCPP_ERROR(logger_, "Failed to run inference");
      throw std::runtime_error("TensorRT inference execution failed");
    }

    CHECK_CUDA(cudaStreamSynchronize(stream));
    CHECK_CUDA(cudaEventRecord(end_event, stream));
    CHECK_CUDA(cudaEventSynchronize(end_event));

    float inference_time_ms = 0.0f;
    CHECK_CUDA(cudaEventElapsedTime(&inference_time_ms, start_event, end_event));
    RCLCPP_INFO(logger_, "TRT Engine : %.3f ms", inference_time_ms);

    // Copy outputs from device
    CHECK_CUDA(cudaMemcpyAsync(
      outputs_classes.data(), d_outputs_classes, sizeof(float) * outputs_classes_size,
      cudaMemcpyDeviceToHost, stream));
    CHECK_CUDA(cudaMemcpyAsync(
      outputs_coords.data(), d_outputs_coords, sizeof(float) * outputs_coords_size,
      cudaMemcpyDeviceToHost, stream));
    CHECK_CUDA(cudaMemcpyAsync(
      bev_embed_output.data(), d_bev_embed, sizeof(float) * bev_embed_size, cudaMemcpyDeviceToHost,
      stream));

    CHECK_CUDA(cudaStreamSynchronize(stream));
  } catch (const std::exception & e) {
    RCLCPP_ERROR(logger_, "Exception during inference: %s", e.what());
    // Cleanup events and stream
    CHECK_CUDA(cudaEventDestroy(start_event));
    CHECK_CUDA(cudaEventDestroy(end_event));
    CHECK_CUDA(cudaStreamDestroy(stream));
    return std::make_tuple(std::vector<float>(), std::vector<float>(), std::vector<float>());
  }

  CHECK_CUDA(cudaEventDestroy(start_event));
  CHECK_CUDA(cudaEventDestroy(end_event));
  CHECK_CUDA(cudaStreamDestroy(stream));

  return std::make_tuple(outputs_classes, outputs_coords, bev_embed_output);
}

bool BEVFormerInferenceEngine::validateInputs(
  const cv::Mat & img_tensor, const std::vector<float> & prev_bev,
  const std::vector<float> & can_bus, const std::vector<float> & lidar2img_flat)
{
  // Calculate expected sizes based on tensor shapes
  size_t expected_img_size = 1;
  for (const auto & dim : input_shape_image_) {
    expected_img_size *= dim;
  }

  size_t expected_prev_bev_size = 1;
  for (const auto & dim : input_shape_prev_bev_) {
    expected_prev_bev_size *= dim;
  }

  size_t expected_can_bus_size = input_shape_can_bus_[0];
  size_t expected_lidar2img_size = 1;
  for (const auto & dim : input_shape_lidar2img_) {
    expected_lidar2img_size *= dim;
  }

  // Check image tensor
  if (img_tensor.total() != expected_img_size) {
    RCLCPP_ERROR(
      logger_, "Invalid image tensor size: %zu, expected: %zu", img_tensor.total(),
      expected_img_size);
    return false;
  }

  // Check data type of image tensor
  if (img_tensor.type() != CV_32F) {
    RCLCPP_ERROR(
      logger_, "Invalid image tensor data type: %d, expected: %d (CV_32F)", img_tensor.type(),
      CV_32F);
    return false;
  }

  // Check prev_bev
  if (prev_bev.size() != expected_prev_bev_size) {
    RCLCPP_ERROR(
      logger_, "Invalid prev_bev size: %zu, expected: %zu", prev_bev.size(),
      expected_prev_bev_size);
    return false;
  }

  // Check can_bus
  if (can_bus.size() != expected_can_bus_size) {
    RCLCPP_ERROR(
      logger_, "Invalid can_bus size: %zu, expected: %zu", can_bus.size(), expected_can_bus_size);
    return false;
  }

  // Check lidar2img
  if (lidar2img_flat.size() != expected_lidar2img_size) {
    RCLCPP_ERROR(
      logger_, "Invalid lidar2img size: %zu, expected: %zu", lidar2img_flat.size(),
      expected_lidar2img_size);
    return false;
  }

  // Check for NaN or inf values in inputs
  auto check_nan_inf = [this](const std::vector<float> & data, const std::string & name) -> bool {
    for (size_t i = 0; i < std::min<size_t>(100, data.size()); ++i) {
      if (std::isnan(data[i]) || std::isinf(data[i])) {
        RCLCPP_ERROR(logger_, "%s contains NaN or Inf at index %zu: %f", name.c_str(), i, data[i]);
        return false;
      }
    }
    return true;
  };

  if (
    !check_nan_inf(prev_bev, "prev_bev") || !check_nan_inf(can_bus, "can_bus") ||
    !check_nan_inf(lidar2img_flat, "lidar2img_flat")) {
    return false;
  }

  return true;
}

